KIND = "questions"
SYSTEM = "cardiovascular"
E = {
"cv-5b516d51": {
"en": ["Which statement about the left ventricle is false?",
 ["It has two papillary muscles, anterior and posterior.", "It forms the apex of the heart.", "The mitral valve has two cusps.", "Its wall is about three times thicker than that of the right ventricle.", "Its outflow tract contains the conus arteriosus (infundibulum)."],
 "The conus arteriosus (infundibulum) is the smooth-walled outflow tract of the right ventricle. The outflow tract of the left ventricle is called the aortic vestibule. Because the left ventricle works against systemic pressure, its wall is the thickest of all the chambers.", []],
"fr": ["Quelle affirmation sur le ventricule gauche est fausse ?",
 ["Il possède deux muscles papillaires, antérieur et postérieur.", "Il forme l'apex du cœur.", "La valve mitrale a deux valvules.", "Sa paroi est environ trois fois plus épaisse que celle du ventricule droit.", "Sa chambre de chasse contient le cône artériel (infundibulum)."],
 "Le cône artériel (infundibulum) est la chambre de chasse à paroi lisse du ventricule droit. Celle du ventricule gauche s'appelle le vestibule aortique. Travaillant contre la pression systémique, le ventricule gauche a la paroi la plus épaisse de toutes les cavités.", []],
"de": ["Welche Aussage über die linke Kammer ist falsch?",
 ["Sie hat zwei Papillarmuskeln, einen vorderen und einen hinteren.", "Sie bildet die Herzspitze.", "Die Mitralklappe hat zwei Segel.", "Ihre Wand ist etwa dreimal dicker als die der rechten Kammer.", "Ihr Ausflusstrakt enthält den Conus arteriosus (Infundibulum)."],
 "Der Conus arteriosus (Infundibulum) ist der glattwandige Ausflusstrakt der rechten Kammer. Der Ausflusstrakt der linken Kammer heißt Vestibulum aortae. Da die linke Kammer gegen den Systemdruck arbeitet, hat sie die dickste Wand aller Herzhöhlen.", []],
"es": ["¿Qué afirmación sobre el ventrículo izquierdo es falsa?",
 ["Tiene dos músculos papilares, anterior y posterior.", "Forma el vértice del corazón.", "La válvula mitral tiene dos valvas.", "Su pared es unas tres veces más gruesa que la del ventrículo derecho.", "Su tracto de salida contiene el cono arterioso (infundíbulo)."],
 "El cono arterioso (infundíbulo) es el tracto de salida de pared lisa del ventrículo derecho. El del ventrículo izquierdo se llama vestíbulo aórtico. Como el ventrículo izquierdo trabaja contra la presión sistémica, su pared es la más gruesa de todas las cavidades.", []],
},
"cv-258cd59d": {
"en": ["Which option lists the branches of the aortic arch correctly from right to left?",
 ["Brachiocephalic trunk, left subclavian artery, left common carotid artery", "Left common carotid artery, brachiocephalic trunk, left subclavian artery", "Brachiocephalic trunk, left common carotid artery, left subclavian artery", "Coronary arteries, brachiocephalic trunk, left subclavian artery", "Right subclavian artery, right common carotid artery, left common carotid artery"],
 "The aortic arch usually gives three branches. The brachiocephalic trunk divides behind the right sternoclavicular joint into the right subclavian and right common carotid arteries. The coronary arteries arise from the ascending aorta.", []],
"fr": ["Quelle proposition énumère correctement, de droite à gauche, les branches de la crosse de l'aorte ?",
 ["Tronc brachiocéphalique, artère subclavière gauche, artère carotide commune gauche", "Artère carotide commune gauche, tronc brachiocéphalique, artère subclavière gauche", "Tronc brachiocéphalique, artère carotide commune gauche, artère subclavière gauche", "Artères coronaires, tronc brachiocéphalique, artère subclavière gauche", "Artère subclavière droite, artère carotide commune droite, artère carotide commune gauche"],
 "La crosse de l'aorte donne habituellement trois branches. Le tronc brachiocéphalique se divise derrière l'articulation sterno-claviculaire droite en artères subclavière droite et carotide commune droite. Les artères coronaires naissent de l'aorte ascendante.", []],
"de": ["In welcher Antwort sind die Äste des Aortenbogens von rechts nach links richtig aufgezählt?",
 ["Truncus brachiocephalicus, A. subclavia sinistra, A. carotis communis sinistra", "A. carotis communis sinistra, Truncus brachiocephalicus, A. subclavia sinistra", "Truncus brachiocephalicus, A. carotis communis sinistra, A. subclavia sinistra", "Aa. coronariae, Truncus brachiocephalicus, A. subclavia sinistra", "A. subclavia dextra, A. carotis communis dextra, A. carotis communis sinistra"],
 "Der Aortenbogen gibt meist drei Äste ab. Der Truncus brachiocephalicus teilt sich hinter dem rechten Sternoklavikulargelenk in die rechte A. subclavia und die rechte A. carotis communis. Die Koronararterien entspringen aus der Aorta ascendens.", []],
"es": ["¿En qué opción están correctamente ordenadas de derecha a izquierda las ramas del cayado aórtico?",
 ["Tronco braquiocefálico, arteria subclavia izquierda, arteria carótida común izquierda", "Arteria carótida común izquierda, tronco braquiocefálico, arteria subclavia izquierda", "Tronco braquiocefálico, arteria carótida común izquierda, arteria subclavia izquierda", "Arterias coronarias, tronco braquiocefálico, arteria subclavia izquierda", "Arteria subclavia derecha, arteria carótida común derecha, arteria carótida común izquierda"],
 "El cayado aórtico suele dar tres ramas. El tronco braquiocefálico se divide detrás de la articulación esternoclavicular derecha en la subclavia derecha y la carótida común derecha. Las arterias coronarias nacen de la aorta ascendente.", []],
},
"cv-0bdc88fc": {
"en": ["A 16-year-old hypertensive patient has high blood pressure in the arms and weak, delayed pulses in the legs. The chest X-ray shows notching of the lower borders of the ribs. Enlargement of which vessels causes the notching?",
 ["Posterior intercostal arteries (collateral circulation)", "Lateral thoracic artery", "Bronchial arteries", "Coronary arteries", "Anterior intercostal veins"],
 "In coarctation of the aorta (usually at the level of the ligamentum arteriosum) blood reaches the descending aorta via subclavian artery → internal thoracic artery → anterior intercostal arteries → posterior intercostal arteries. The enlarged posterior intercostal arteries erode the lower borders of the ribs (ribs 3–8).", []],
"fr": ["Un patient hypertendu de 16 ans a une pression artérielle élevée aux bras et des pouls faibles et retardés aux jambes. La radiographie thoracique montre des encoches au bord inférieur des côtes. La dilatation de quels vaisseaux en est la cause ?",
 ["Artères intercostales postérieures (circulation collatérale)", "Artère thoracique latérale", "Artères bronchiques", "Artères coronaires", "Veines intercostales antérieures"],
 "Dans la coarctation de l'aorte (le plus souvent au niveau du ligament artériel), le sang gagne l'aorte descendante par la voie artère subclavière → artère thoracique interne → artères intercostales antérieures → artères intercostales postérieures. Les intercostales postérieures dilatées érodent le bord inférieur des côtes (3e à 8e côtes).", []],
"de": ["Ein 16-jähriger Hypertoniker hat erhöhten Blutdruck an den Armen und schwache, verzögerte Beinpulse. Das Thoraxröntgen zeigt Usuren an den Rippenunterrändern. Die Erweiterung welcher Gefäße verursacht die Usuren?",
 ["Aa. intercostales posteriores (Kollateralkreislauf)", "A. thoracica lateralis", "Aa. bronchiales", "Aa. coronariae", "Vv. intercostales anteriores"],
 "Bei der Aortenisthmusstenose (meist in Höhe des Lig. arteriosum) gelangt das Blut über A. subclavia → A. thoracica interna → vordere Interkostalarterien → hintere Interkostalarterien in die absteigende Aorta. Die erweiterten hinteren Interkostalarterien arrodieren die Rippenunterränder (3.–8. Rippe).", []],
"es": ["Un paciente hipertenso de 16 años tiene presión arterial alta en los brazos y pulsos débiles y retrasados en las piernas. La radiografía de tórax muestra muescas en el borde inferior de las costillas. ¿La dilatación de qué vasos las produce?",
 ["Arterias intercostales posteriores (circulación colateral)", "Arteria torácica lateral", "Arterias bronquiales", "Arterias coronarias", "Venas intercostales anteriores"],
 "En la coartación de aorta (generalmente a la altura del ligamento arterioso) la sangre llega a la aorta descendente por la vía arteria subclavia → arteria torácica interna → intercostales anteriores → intercostales posteriores. Las intercostales posteriores dilatadas erosionan el borde inferior de las costillas (3.ª a 8.ª).", []],
},
"cv-f7249148": {
"en": ["At which level does the abdominal aorta divide into the two common iliac arteries?",
 ["L2", "L4 (about the level of the umbilicus)", "L1", "T12", "S2"],
 "After the aortic hiatus (T12) the abdominal aorta descends to the left of the spine and divides at L4; this point corresponds roughly to just below the umbilicus and to the line of the iliac crests.", []],
"fr": ["À quel niveau l'aorte abdominale se divise-t-elle en deux artères iliaques communes ?",
 ["L2", "L4 (environ à hauteur de l'ombilic)", "L1", "T12", "S2"],
 "Après le hiatus aortique (T12), l'aorte abdominale descend à gauche du rachis et se divise en L4 ; ce point correspond à peu près à la région juste sous l'ombilic et à la ligne des crêtes iliaques.", []],
"de": ["In welcher Höhe teilt sich die Bauchaorta in die beiden Aa. iliacae communes?",
 ["L2", "L4 (etwa Nabelhöhe)", "L1", "T12", "S2"],
 "Nach dem Hiatus aorticus (T12) zieht die Bauchaorta links der Wirbelsäule nach unten und teilt sich in Höhe L4; dieser Punkt liegt etwa knapp unter dem Nabel und auf der Verbindungslinie der Darmbeinkämme.", []],
"es": ["¿A qué nivel se divide la aorta abdominal en las dos arterias ilíacas comunes?",
 ["L2", "L4 (aproximadamente a la altura del ombligo)", "L1", "T12", "S2"],
 "Tras el hiato aórtico (T12), la aorta abdominal desciende a la izquierda de la columna y se divide en L4; este punto corresponde aproximadamente a justo debajo del ombligo y a la línea de las crestas ilíacas.", []],
},
"cv-dc7a4413": {
"en": ["A pulsatile abdominal mass is found in a 70-year-old male smoker. Where are abdominal aortic aneurysms most commonly located?",
 ["At the level of the origins of the renal arteries", "At the aortic hiatus", "Above the coeliac trunk", "Below the renal arteries (infrarenal), above the bifurcation", "In the external iliac artery"],
 "Most abdominal aortic aneurysms are infrarenal. In this region there are few vasa vasorum and the elastin content is low. The risk of rupture increases with diameter.", []],
"fr": ["Une masse abdominale battante est découverte chez un fumeur de 70 ans. Où siègent le plus souvent les anévrismes de l'aorte abdominale ?",
 ["Au niveau de l'origine des artères rénales", "Au hiatus aortique", "Au-dessus du tronc cœliaque", "Sous les artères rénales (sous-rénal), au-dessus de la bifurcation", "Dans l'artère iliaque externe"],
 "La grande majorité des anévrismes de l'aorte abdominale sont sous-rénaux. Dans cette région, les vasa vasorum sont rares et la teneur en élastine est faible. Le risque de rupture augmente avec le diamètre.", []],
"de": ["Bei einem 70-jährigen Raucher wird eine pulsierende Bauchmasse getastet. Wo liegen Bauchaortenaneurysmen am häufigsten?",
 ["In Höhe der Nierenarterienabgänge", "Am Hiatus aorticus", "Oberhalb des Truncus coeliacus", "Unterhalb der Nierenarterien (infrarenal), oberhalb der Bifurkation", "In der A. iliaca externa"],
 "Die meisten Bauchaortenaneurysmen liegen infrarenal. In diesem Abschnitt gibt es wenig Vasa vasorum und der Elastingehalt ist niedrig. Das Rupturrisiko steigt mit dem Durchmesser.", []],
"es": ["Se detecta una masa abdominal pulsátil en un fumador de 70 años. ¿Dónde se localizan con más frecuencia los aneurismas de aorta abdominal?",
 ["A la altura del origen de las arterias renales", "En el hiato aórtico", "Por encima del tronco celíaco", "Por debajo de las arterias renales (infrarrenal), por encima de la bifurcación", "En la arteria ilíaca externa"],
 "La gran mayoría de los aneurismas de aorta abdominal son infrarrenales. En esta zona hay pocos vasa vasorum y el contenido de elastina es bajo. El riesgo de rotura aumenta con el diámetro.", []],
},
"cv-7d92b3b7": {
"en": ["At which level does the common carotid artery usually divide into the internal and external carotid arteries?",
 ["Upper border of the thyroid cartilage (C4)", "Level of the cricoid cartilage (C6)", "Above the angle of the mandible (C2)", "Body of the hyoid bone (C3)", "Level of the sternoclavicular joint"],
 "The carotid bifurcation lies at the level of the upper border of the thyroid cartilage. Here the dilatation at the start of the ICA (carotid sinus) is a baroreceptor and the small body at the bifurcation (carotid body) a chemoreceptor; both are supplied by the glossopharyngeal nerve.", []],
"fr": ["À quel niveau l'artère carotide commune se divise-t-elle habituellement en carotides interne et externe ?",
 ["Bord supérieur du cartilage thyroïde (C4)", "Niveau du cartilage cricoïde (C6)", "Au-dessus de l'angle de la mandibule (C2)", "Corps de l'os hyoïde (C3)", "Niveau de l'articulation sterno-claviculaire"],
 "La bifurcation carotidienne se situe à hauteur du bord supérieur du cartilage thyroïde. La dilatation à l'origine de la carotide interne (sinus carotidien) est un barorécepteur et le petit corps de la bifurcation (glomus carotidien) un chémorécepteur ; tous deux sont innervés par le nerf glossopharyngien.", []],
"de": ["In welcher Höhe teilt sich die A. carotis communis meist in A. carotis interna und externa?",
 ["Oberrand des Schildknorpels (C4)", "Höhe des Ringknorpels (C6)", "Oberhalb des Kieferwinkels (C2)", "Zungenbeinkörper (C3)", "Höhe des Sternoklavikulargelenks"],
 "Die Karotisgabel liegt in Höhe des Schildknorpel-Oberrands. Die Erweiterung am Anfang der ACI (Sinus caroticus) ist ein Barorezeptor, das kleine Körperchen an der Gabel (Glomus caroticum) ein Chemorezeptor; beide werden vom N. glossopharyngeus innerviert.", []],
"es": ["¿A qué nivel suele dividirse la arteria carótida común en carótidas interna y externa?",
 ["Borde superior del cartílago tiroides (C4)", "Nivel del cartílago cricoides (C6)", "Por encima del ángulo de la mandíbula (C2)", "Cuerpo del hueso hioides (C3)", "Nivel de la articulación esternoclavicular"],
 "La bifurcación carotídea está a la altura del borde superior del cartílago tiroides. La dilatación del inicio de la ACI (seno carotídeo) es un barorreceptor y el pequeño cuerpo de la bifurcación (cuerpo carotídeo) un quimiorreceptor; ambos están inervados por el nervio glosofaríngeo.", []],
},
"cv-64588484": {
"en": ["Carotid sinus massage is performed on a patient with supraventricular tachycardia. What are the afferent and efferent pathways of the fall in heart rate?",
 ["Afferent: vagus nerve – Efferent: glossopharyngeal nerve", "Afferent: hypoglossal nerve – Efferent: vagus nerve", "Afferent: glossopharyngeal nerve – Efferent: vagus nerve", "Afferent: sympathetic chain – Efferent: phrenic nerve", "Afferent: accessory nerve – Efferent: vagus nerve"],
 "The baroreceptors of the carotid sinus report the rise in pressure to the brainstem through the carotid sinus branch of CN IX; in response vagal output increases and the heart slows. In the elderly hypersensitivity can cause syncope.", []],
"fr": ["Un massage du sinus carotidien est réalisé chez un patient en tachycardie supraventriculaire. Quelles sont les voies afférente et efférente du ralentissement cardiaque ?",
 ["Afférente : nerf vague – Efférente : nerf glossopharyngien", "Afférente : nerf hypoglosse – Efférente : nerf vague", "Afférente : nerf glossopharyngien – Efférente : nerf vague", "Afférente : chaîne sympathique – Efférente : nerf phrénique", "Afférente : nerf accessoire – Efférente : nerf vague"],
 "Les barorécepteurs du sinus carotidien signalent la hausse de pression au tronc cérébral par le rameau du sinus carotidien du IX ; en réponse, le tonus vagal augmente et le cœur ralentit. Chez le sujet âgé, une hypersensibilité peut provoquer une syncope.", []],
"de": ["Bei einem Patienten mit supraventrikulärer Tachykardie wird eine Karotissinusmassage durchgeführt. Welches sind afferenter und efferenter Schenkel der Herzfrequenzsenkung?",
 ["Afferent: N. vagus – Efferent: N. glossopharyngeus", "Afferent: N. hypoglossus – Efferent: N. vagus", "Afferent: N. glossopharyngeus – Efferent: N. vagus", "Afferent: Grenzstrang – Efferent: N. phrenicus", "Afferent: N. accessorius – Efferent: N. vagus"],
 "Die Barorezeptoren des Sinus caroticus melden den Druckanstieg über den Karotissinusast des IX. Hirnnervs an den Hirnstamm; daraufhin steigt der Vagustonus und die Herzfrequenz sinkt. Bei älteren Menschen kann eine Überempfindlichkeit zu Synkopen führen.", []],
"es": ["Se realiza masaje del seno carotídeo a un paciente con taquicardia supraventricular. ¿Cuáles son las vías aferente y eferente del descenso de la frecuencia cardíaca?",
 ["Aferente: nervio vago – Eferente: nervio glosofaríngeo", "Aferente: nervio hipogloso – Eferente: nervio vago", "Aferente: nervio glosofaríngeo – Eferente: nervio vago", "Aferente: cadena simpática – Eferente: nervio frénico", "Aferente: nervio accesorio – Eferente: nervio vago"],
 "Los barorreceptores del seno carotídeo informan del aumento de presión al tronco encefálico por la rama del seno carotídeo del IX par; como respuesta aumenta el tono vagal y el corazón se enlentece. En los ancianos la hipersensibilidad puede causar síncope.", []],
},
"cv-b380c127": {
"en": ["Which artery gives no branches at all in the neck?",
 ["Vertebral artery", "Internal carotid artery", "External carotid artery", "Thyrocervical trunk", "Subclavian artery"],
 "The internal carotid artery enters the carotid canal without branching in the neck; its first important branch is the ophthalmic artery inside the skull. This helps surgeons tell the ICA from the ECA.", []],
"fr": ["Quelle artère ne donne aucune branche au cou ?",
 ["Artère vertébrale", "Artère carotide interne", "Artère carotide externe", "Tronc thyro-cervical", "Artère subclavière"],
 "L'artère carotide interne pénètre dans le canal carotidien sans se ramifier au cou ; sa première branche importante est l'artère ophtalmique, dans le crâne. Cette particularité permet au chirurgien de distinguer la carotide interne de l'externe.", []],
"de": ["Welche Arterie gibt am Hals überhaupt keine Äste ab?",
 ["A. vertebralis", "A. carotis interna", "A. carotis externa", "Truncus thyrocervicalis", "A. subclavia"],
 "Die A. carotis interna tritt ohne Halsäste in den Canalis caroticus; ihr erster wichtiger Ast ist die A. ophthalmica im Schädel. Dieses Merkmal hilft in der Chirurgie, die ACI von der ACE zu unterscheiden.", []],
"es": ["¿Qué arteria no da ninguna rama en el cuello?",
 ["Arteria vertebral", "Arteria carótida interna", "Arteria carótida externa", "Tronco tirocervical", "Arteria subclavia"],
 "La arteria carótida interna entra en el conducto carotídeo sin dar ramas en el cuello; su primera rama importante es la arteria oftálmica dentro del cráneo. Esto ayuda al cirujano a distinguir la ACI de la ACE.", []],
},
"cv-d408d339": {
"en": ["Which of the following is NOT a branch of the external carotid artery?",
 ["Maxillary artery", "Facial artery", "Lingual artery", "Superior thyroid artery", "Ophthalmic artery"],
 "Branches of the ECA: superior thyroid, ascending pharyngeal, lingual, facial, occipital and posterior auricular arteries, and the terminal maxillary and superficial temporal arteries. The ophthalmic artery is the first intracranial branch of the ICA.", []],
"fr": ["Laquelle de ces artères n'est PAS une branche de la carotide externe ?",
 ["Artère maxillaire", "Artère faciale", "Artère linguale", "Artère thyroïdienne supérieure", "Artère ophtalmique"],
 "Branches de la carotide externe : artères thyroïdienne supérieure, pharyngienne ascendante, linguale, faciale, occipitale, auriculaire postérieure et les branches terminales maxillaire et temporale superficielle. L'artère ophtalmique est la première branche intracrânienne de la carotide interne.", []],
"de": ["Welche der folgenden Arterien ist KEIN Ast der A. carotis externa?",
 ["A. maxillaris", "A. facialis", "A. lingualis", "A. thyroidea superior", "A. ophthalmica"],
 "Äste der ACE: A. thyroidea superior, A. pharyngea ascendens, A. lingualis, A. facialis, A. occipitalis, A. auricularis posterior sowie die Endäste A. maxillaris und A. temporalis superficialis. Die A. ophthalmica ist der erste intrakranielle Ast der ACI.", []],
"es": ["¿Cuál de las siguientes NO es rama de la arteria carótida externa?",
 ["Arteria maxilar", "Arteria facial", "Arteria lingual", "Arteria tiroidea superior", "Arteria oftálmica"],
 "Ramas de la ACE: arterias tiroidea superior, faríngea ascendente, lingual, facial, occipital y auricular posterior, y las terminales maxilar y temporal superficial. La arteria oftálmica es la primera rama intracraneal de la ACI.", []],
},
"cv-c6279338": {
"en": ["The middle meningeal artery is a branch of which artery?",
 ["Internal carotid artery", "Occipital artery", "Ophthalmic artery", "Maxillary artery", "Superficial temporal artery"],
 "The maxillary artery gives off the middle meningeal artery in the infratemporal fossa; it enters the skull through the foramen spinosum and supplies most of the dura and the skull bones.", []],
"fr": ["L'artère méningée moyenne est une branche de quelle artère ?",
 ["Artère carotide interne", "Artère occipitale", "Artère ophtalmique", "Artère maxillaire", "Artère temporale superficielle"],
 "L'artère maxillaire donne l'artère méningée moyenne dans la fosse infratemporale ; celle-ci entre dans le crâne par le foramen épineux et vascularise la plus grande partie de la dure-mère et des os du crâne.", []],
"de": ["Die A. meningea media ist ein Ast welcher Arterie?",
 ["A. carotis interna", "A. occipitalis", "A. ophthalmica", "A. maxillaris", "A. temporalis superficialis"],
 "Die A. maxillaris gibt in der Fossa infratemporalis die A. meningea media ab; diese tritt durch das Foramen spinosum in den Schädel und versorgt den größten Teil der Dura und der Schädelknochen.", []],
"es": ["¿De qué arteria es rama la arteria meníngea media?",
 ["Arteria carótida interna", "Arteria occipital", "Arteria oftálmica", "Arteria maxilar", "Arteria temporal superficial"],
 "La arteria maxilar da la meníngea media en la fosa infratemporal; esta entra en el cráneo por el agujero espinoso e irriga la mayor parte de la duramadre y los huesos del cráneo.", []],
},
"cv-7afbacff": {
"en": ["Where on the face is the pulse of the facial artery most easily felt?",
 ["Behind the angle of the mandible", "Over the infraorbital foramen", "At the medial angle of the eye", "In front of the tragus", "At the anterior border of masseter, on the lower border of the mandible"],
 "The facial artery crosses the lower border of the mandible at the anterior border of masseter, where it can be felt against the bone. It runs a tortuous course from the corner of the mouth to the medial angle of the eye (angular artery).", []],
"fr": ["Où le pouls de l'artère faciale se prend-il le plus facilement sur le visage ?",
 ["Derrière l'angle de la mandibule", "Sur le foramen infra-orbitaire", "À l'angle médial de l'œil", "Devant le tragus", "Au bord antérieur du masséter, sur le bord inférieur de la mandibule"],
 "L'artère faciale croise le bord inférieur de la mandibule au bord antérieur du masséter, où on la sent en la comprimant contre l'os. Elle suit un trajet sinueux de la commissure des lèvres à l'angle médial de l'œil (artère angulaire).", []],
"de": ["Wo ist der Puls der A. facialis im Gesicht am leichtesten zu tasten?",
 ["Hinter dem Kieferwinkel", "Über dem Foramen infraorbitale", "Am inneren Augenwinkel", "Vor dem Tragus", "Am Vorderrand des M. masseter auf dem Unterkieferrand"],
 "Die A. facialis überquert den Unterkieferrand am Vorderrand des M. masseter und ist dort gegen den Knochen tastbar. Sie zieht geschlängelt vom Mundwinkel zum inneren Augenwinkel (A. angularis).", []],
"es": ["¿Dónde se palpa con más facilidad en la cara el pulso de la arteria facial?",
 ["Detrás del ángulo de la mandíbula", "Sobre el agujero infraorbitario", "En el ángulo interno del ojo", "Delante del trago", "En el borde anterior del masetero, sobre el borde inferior de la mandíbula"],
 "La arteria facial cruza el borde inferior de la mandíbula en el borde anterior del masetero, donde se palpa contra el hueso. Sigue un trayecto sinuoso desde la comisura bucal al ángulo interno del ojo (arteria angular).", []],
},
"cv-937ce9d9": {
"en": ["A 70-year-old woman has new temple pain, jaw pain on chewing and blurred vision; the ESR is raised. From which artery is a biopsy most often taken for diagnosis?",
 ["Facial artery", "Internal carotid artery", "Maxillary artery", "Superficial temporal artery", "Occipital artery"],
 "Giant cell (temporal) arteritis involves medium and large arteries, especially branches of the ECA. The superficial temporal artery, easily felt in front of the tragus, is suitable for biopsy. If treatment is delayed, involvement of the ophthalmic artery can cause permanent blindness.", []],
"fr": ["Une femme de 70 ans présente des céphalées temporales récentes, une claudication de la mâchoire et une vision floue ; la VS est élevée. Sur quelle artère fait-on le plus souvent la biopsie diagnostique ?",
 ["Artère faciale", "Artère carotide interne", "Artère maxillaire", "Artère temporale superficielle", "Artère occipitale"],
 "L'artérite à cellules géantes (maladie de Horton) touche les artères de moyen et gros calibre, surtout les branches de la carotide externe. L'artère temporale superficielle, facilement palpable devant le tragus, se prête à la biopsie. Si le traitement tarde, l'atteinte de l'artère ophtalmique peut causer une cécité définitive.", []],
"de": ["Eine 70-jährige Frau hat neu aufgetretene Schläfenkopfschmerzen, Kieferschmerzen beim Kauen und verschwommenes Sehen; die BSG ist erhöht. Aus welcher Arterie wird zur Diagnose meist eine Biopsie entnommen?",
 ["A. facialis", "A. carotis interna", "A. maxillaris", "A. temporalis superficialis", "A. occipitalis"],
 "Die Riesenzellarteriitis (Arteriitis temporalis) befällt mittlere und große Arterien, besonders Äste der ACE. Die vor dem Tragus leicht tastbare A. temporalis superficialis eignet sich zur Biopsie. Bei verzögerter Therapie kann eine Beteiligung der A. ophthalmica zur bleibenden Erblindung führen.", []],
"es": ["Una mujer de 70 años presenta dolor temporal de nueva aparición, dolor mandibular al masticar y visión borrosa; la VSG está elevada. ¿De qué arteria se toma con más frecuencia la biopsia diagnóstica?",
 ["Arteria facial", "Arteria carótida interna", "Arteria maxilar", "Arteria temporal superficial", "Arteria occipital"],
 "La arteritis de células gigantes (temporal) afecta a arterias de mediano y gran calibre, sobre todo ramas de la ACE. La arteria temporal superficial, fácil de palpar delante del trago, es adecuada para la biopsia. Si el tratamiento se retrasa, la afectación de la arteria oftálmica puede causar ceguera permanente.", []],
},
"cv-43492b44": {
"en": ["The posterior inferior cerebellar artery (PICA) is a branch of which artery?",
 ["Basilar artery", "Vertebral artery", "Internal carotid artery", "Posterior cerebral artery", "Anterior spinal artery"],
 "PICA is usually the largest intracranial branch of the vertebral artery. AICA and SCA arise from the basilar artery, which divides at the upper border of the pons into the two PCAs. Occlusion of PICA causes lateral medullary syndrome.", []],
"fr": ["L'artère cérébelleuse postéro-inférieure (PICA) est une branche de quelle artère ?",
 ["Artère basilaire", "Artère vertébrale", "Artère carotide interne", "Artère cérébrale postérieure", "Artère spinale antérieure"],
 "La PICA est en général la plus grosse branche intracrânienne de l'artère vertébrale. L'AICA et l'artère cérébelleuse supérieure naissent de la basilaire, qui se divise au bord supérieur du pont en deux cérébrales postérieures. L'occlusion de la PICA provoque le syndrome de Wallenberg (syndrome latéral du bulbe).", []],
"de": ["Die A. inferior posterior cerebelli (PICA) ist ein Ast welcher Arterie?",
 ["A. basilaris", "A. vertebralis", "A. carotis interna", "A. cerebri posterior", "A. spinalis anterior"],
 "Die PICA ist meist der größte intrakranielle Ast der A. vertebralis. AICA und A. superior cerebelli entspringen aus der A. basilaris, die sich am Oberrand der Brücke in die beiden Aa. cerebri posteriores teilt. Ein PICA-Verschluss verursacht das Wallenberg-Syndrom (laterales Medulla-oblongata-Syndrom).", []],
"es": ["¿De qué arteria es rama la arteria cerebelosa posteroinferior (PICA)?",
 ["Arteria basilar", "Arteria vertebral", "Arteria carótida interna", "Arteria cerebral posterior", "Arteria espinal anterior"],
 "La PICA suele ser la mayor rama intracraneal de la arteria vertebral. La AICA y la cerebelosa superior nacen de la basilar, que se divide en el borde superior de la protuberancia en las dos cerebrales posteriores. La oclusión de la PICA produce el síndrome bulbar lateral (de Wallenberg).", []],
},
"cv-0adf4674": {
"en": ["Which of the following arteries is NOT part of the circle of Willis (circulus arteriosus cerebri)?",
 ["Anterior cerebral artery (A1 segment)", "Posterior communicating artery", "Anterior communicating artery", "Posterior cerebral artery (P1 segment)", "Middle cerebral artery"],
 "The circle of Willis is formed by the ACom, the A1 segments of both ACAs, the terminal parts of both ICAs, both PComs and the P1 segments of both PCAs. The MCA continues the ICA but is not part of the ring.", []],
"fr": ["Laquelle de ces artères ne fait PAS partie du polygone de Willis (cercle artériel du cerveau) ?",
 ["Artère cérébrale antérieure (segment A1)", "Artère communicante postérieure", "Artère communicante antérieure", "Artère cérébrale postérieure (segment P1)", "Artère cérébrale moyenne"],
 "Le polygone de Willis est formé par la communicante antérieure, les segments A1 des deux cérébrales antérieures, la terminaison des deux carotides internes, les deux communicantes postérieures et les segments P1 des deux cérébrales postérieures. La cérébrale moyenne prolonge la carotide interne mais ne fait pas partie de l'anneau.", []],
"de": ["Welche der folgenden Arterien gehört NICHT zum Circulus arteriosus cerebri (Willisii)?",
 ["A. cerebri anterior (A1-Abschnitt)", "A. communicans posterior", "A. communicans anterior", "A. cerebri posterior (P1-Abschnitt)", "A. cerebri media"],
 "Den Circulus Willisii bilden die A. communicans anterior, die A1-Abschnitte beider ACA, die Endabschnitte beider ACI, beide Aa. communicantes posteriores und die P1-Abschnitte beider PCA. Die A. cerebri media setzt die ACI fort, gehört aber nicht zum Ring.", []],
"es": ["¿Cuál de las siguientes arterias NO forma parte del polígono de Willis (círculo arterial del cerebro)?",
 ["Arteria cerebral anterior (segmento A1)", "Arteria comunicante posterior", "Arteria comunicante anterior", "Arteria cerebral posterior (segmento P1)", "Arteria cerebral media"],
 "El polígono de Willis lo forman la comunicante anterior, los segmentos A1 de ambas cerebrales anteriores, los extremos de ambas carótidas internas, ambas comunicantes posteriores y los segmentos P1 de ambas cerebrales posteriores. La cerebral media continúa la ACI pero no forma parte del anillo.", []],
},
"cv-11e9072b": {
"en": ["A 65-year-old patient has sudden painless complete loss of vision in one eye. On fundoscopy the retina is pale and the macula has a 'cherry-red spot'. Which artery is occluded?",
 ["Lacrimal artery", "Posterior cerebral artery", "Long posterior ciliary artery", "Supraorbital artery", "Central retinal artery"],
 "The central retinal artery is a branch of the ophthalmic artery and enters the eye within the optic nerve. Being an end artery, its occlusion makes the inner layers of the retina ischaemic; the fovea, supplied by the choroid, appears as a red spot.", []],
"fr": ["Un patient de 65 ans présente une perte brutale, indolore et complète de la vision d'un œil. Au fond d'œil, la rétine est pâle et la macula « rouge cerise ». Quelle artère est occluse ?",
 ["Artère lacrymale", "Artère cérébrale postérieure", "Artère ciliaire postérieure longue", "Artère supra-orbitaire", "Artère centrale de la rétine"],
 "L'artère centrale de la rétine est une branche de l'ophtalmique et pénètre dans l'œil à l'intérieur du nerf optique. Artère terminale, son occlusion rend ischémiques les couches internes de la rétine ; la fovéa, nourrie par la choroïde, apparaît comme une tache rouge.", []],
"de": ["Ein 65-jähriger Patient hat einen plötzlichen, schmerzlosen, vollständigen Sehverlust eines Auges. Im Fundus ist die Netzhaut blass, die Makula zeigt einen „kirschroten Fleck“. Welche Arterie ist verschlossen?",
 ["A. lacrimalis", "A. cerebri posterior", "A. ciliaris posterior longa", "A. supraorbitalis", "A. centralis retinae"],
 "Die A. centralis retinae ist ein Ast der A. ophthalmica und tritt im N. opticus ins Auge. Als Endarterie führt ihr Verschluss zur Ischämie der inneren Netzhautschichten; die von der Aderhaut versorgte Fovea erscheint als roter Fleck.", []],
"es": ["Un paciente de 65 años presenta pérdida súbita, indolora y completa de la visión de un ojo. En el fondo de ojo la retina está pálida y la mácula muestra una «mancha rojo cereza». ¿Qué arteria está ocluida?",
 ["Arteria lagrimal", "Arteria cerebral posterior", "Arteria ciliar posterior larga", "Arteria supraorbitaria", "Arteria central de la retina"],
 "La arteria central de la retina es rama de la oftálmica y entra en el ojo por dentro del nervio óptico. Al ser terminal, su oclusión deja isquémicas las capas internas de la retina; la fóvea, nutrida por la coroides, se ve como una mancha roja.", []],
},
}
